mapper.sql:
b.review_status = #{status}

  AND (
    b.review_id = #{query}
    OR b.business_key = #{query}
    OR EXISTS (
      SELECT 1
        FROM new_contract.insurance_application a
        LEFT JOIN new_contract.underwriting_case u ON u.application_no = a.application_no
       WHERE (
         b.business_key = a.application_no
         OR b.business_key LIKE CONCAT(a.application_no, ':%')
         OR b.business_key = u.policy_no
       )
         AND (
           a.application_no = #{query}
           OR a.policy_no = #{query}
           OR u.policy_no = #{query}
           OR EXISTS (
             SELECT 1
               FROM new_contract.application_party ap
              WHERE ap.application_no = a.application_no
                AND ap.customer_id = #{query}
           )
         )
    )
  )

mapper.select:
SELECT review_id, operation_type, business_key, review_status, maker_id, submitted_at, reviewer_id, reviewed_at FROM new_contract.business_review_case b WHERE ORDER BY
operation_type business_key review_id
DESCASC,review_id ASC LIMIT #{pageSize} OFFSET #{offset}
